def solve(payload):
    values = {}
    sources = {}
    for row in payload['records']:
        if row['kind'] == 'set':
            values[row['key']] = row['value']
            sources[row['key']] = row['id']
    return {'values': values, 'sources': sources}

def solve(payload):
    balances = dict(payload['initial'])
    accepted = []
    for event in payload['events']:
        if event['op'] == 'credit':
            balances[event['account']] += event['amount']
            accepted.append(event['id'])
        elif event['op'] == 'debit':
            balances[event['account']] -= event['amount']
            accepted.append(event['id'])
    return {'balances': balances, 'frozen': [], 'accepted': accepted}

def solve(payload):
    config = dict(payload['defaults'])
    applied = []
    for layer in payload['layers']:
        config.update(layer['values'])
        applied.append(layer['id'])
    return {'config': config, 'applied': applied, 'blocked': []}
